theorem isLocalization_map (M : Submonoid B) [Algebra B B'] [IsLocalization M B'] :
    @IsLocalization _ _ (M.map (algebraMap B (J c))) (J (algebraMap B B' ∘ c)) _
      (map (algebraMap B B') c).toAlgebra

